        question: "\u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u0623\u0628\u0639\u0627\u062F \u0643\u0645\u064A\u0629 \u0645\u0639\u064A\u0646\u0629 \u0647\u064A M L\xB2 T\u207B\xB2\u060C \u0641\u0647\u0630\u0647 \u0627\u0644\u0643\u0645\u064A\u0629 \u062A\u0645\u062B\u0644:",
