  "lessonTitle": "\u{1F4DA} \u0627\u0633\u0645 \u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u0645\u0633\u062A\u062E\u0631\u062C \u0645\u0646 \u0627\u0644\u0645\u062D\u062A\u0648\u0649 \u0628\u062F\u0642\u0629",
  "subjectName": "\u0627\u0633\u0645 \u0627\u0644\u0645\u0627\u062F\u0629 (\u0645\u062B\u0644: \u0641\u064A\u0632\u064A\u0627\u0621 1 / \u062F\u0648\u0627\u0626\u0631 \u0643\u0647\u0631\u0628\u0627\u0626\u064A\u0629 1 / \u062A\u0641\u0627\u0636\u0644 \u0648\u062A\u0643\u0627\u0645\u0644 1 / \u0645\u064A\u0643\u0627\u0646\u064A\u0643\u0627 \u0647\u0646\u062F\u0633\u064A\u0629 / \u0643\u064A\u0645\u064A\u0627\u0621 \u0647\u0646\u062F\u0633\u064A\u0629 / \u0645\u0642\u062F\u0645\u0629 \u0645\u064A\u0643\u0627\u062A\u0631\u0648\u0646\u0643\u0633)",
