        isGenerated: true,
        note: "\u062E\u0637\u0623 \u0645\u0639\u062A\u0627\u062F \u0641\u064A \u0627\u0645\u062A\u062D\u0627\u0646\u0627\u062A \u0627\u0644\u0639\u0645\u0644\u064A: \u0646\u0633\u064A\u0627\u0646 \u062A\u062D\u0648\u064A\u0644 \u0627\u0644\u0645\u0644\u064A \u0623\u0645\u0628\u064A\u0631 (mA) \u0625\u0644\u0649 \u0623\u0645\u0628\u064A\u0631 (A) \u0628\u0627\u0644\u0642\u0633\u0645\u0629 \u0639\u0644\u0649 1000 \u064A\u0624\u062F\u064A \u0625\u0644\u0649 \u0645\u0642\u0627\u0648\u0645\u0629 \u062E\u0627\u0637\u0626\u0629 \u062A\u0645\u0627\u0645\u0627\u064B!"
